'use strict';
const scope=root=>typeof root==='string'?document.querySelector(root):root;
const $=(s,root=document)=>scope(root)?.querySelector(s), $$=(s,root=document)=>[...(scope(root)?.querySelectorAll(s)||[])];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'৳'+((n||0)/100).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2});
const numeric=n=>((n||0)/100).toFixed(2);
const csrf=$('meta[name=csrf-token]').content;
let state=null,route='dashboard',renderSequence=0,selectedPeriod='',selectedOrder=null,invoiceKey=crypto.randomUUID();
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',billing:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 7h6M9 11h6M9 15h3"/>',customers:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5"/>',orders:'<path d="M4 6h16v15H4zM8 6V3h8v3M8 11h8M8 15h5"/>',receivables:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',expenses:'<path d="M3 6h18v14H3zM3 6V4h16v2M16 11h5v5h-5z"/>',inventory:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 8v9l9 5 9-5V8M12 13v9"/>',cashflow:'<path d="M4 7h15l-4-4M20 17H5l4 4M19 7l-4 4M5 17l4-4"/>',reports:'<path d="M4 20V4M4 20h17M8 16V9M13 16V5M18 16v-4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z"/>'};
const labels={dashboard:'Overview',billing:'Counter & billing',customers:'Customers',orders:'Online orders',files:'Files',printing:'Print queue',transactions:'Transactions',receivables:'Dues & reminders',expenses:'Expenses & capital',inventory:'Inventory',cashflow:'Cash flow',reports:'Reports',settings:'Settings'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.dashboard}</svg>`;
const badge=(value,color='')=>`<span class="badge ${color}">${esc(value)}</span>`;
const person=c=>`<div class="row-name"><span class="mini-avatar">${esc(c.name.slice(0,2).toUpperCase())}</span><div><b>${esc(c.name)}</b><small>${esc(c.id)} ${c.vip?'· VIP':''}</small></div></div>`;
const table=(headers,body,empty='No records yet.')=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="empty">${esc(empty)}</td></tr>`}</tbody></table></div>`;
const btn=(action,label,cls='secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const opt=(values,selected)=>values.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
const head=(title,subtitle,actions='')=>`<div class="page-head"><div><span class="eyebrow">DIGITXBD WORKSPACE</span><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const methodField=()=>`<label>Payment method<select name="method">${opt(state.methods)}</select></label>`;
const dateField=()=>field('Date','date',state.today,'date','required');
const normalizePhone=v=>String(v||'').replace(/\D/g,'').replace(/^01/,'8801');
const customerField=(selected='')=>`<label>Customer<input name="customer_id" list="customer-list" placeholder="Customer ID or phone number" value="${esc(selected)}" required autocomplete="off"><datalist id="customer-list">${state.customers.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}</datalist><small>Enter a full phone number to find the existing customer ID.</small></label>`;

async function api(path,method='GET',body){const response=await fetch(path,{method,headers:{'X-CSRF-Token':csrf,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});if(response.status===401){location.assign('/login');throw Error('Please sign in.');}let result;try{result=await response.json();}catch{throw Error('The server could not complete this request.');}if(!response.ok)throw Error(result.error||`Request failed (${response.status}).`);return result;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500);}
function modal(title,body,submit=null){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('close-modal','×','icon-button','aria-label="Close"')}</div><div class="modal-body">${body}</div>`;$('#modal').showModal();if(submit){const form=$('form','#modal');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');if(button)button.disabled=true;try{await submit(Object.fromEntries(new FormData(form)),form);}catch(error){toast(error.message);}finally{if(button)button.disabled=false;}});}setTimeout(()=>$('input:not([type=hidden]),select,textarea','#modal')?.focus(),20);}
function closeModal(){if($('#modal').open)$('#modal').close();}
async function reload(){state=await api('/api/bootstrap');$('#footer-date').textContent=new Date(state.today+'T12:00:00').toLocaleDateString('en-BD',{dateStyle:'long'});}
const navigationGroups=[{id:'work',name:'Shop & orders',routes:['billing','customers','orders','files','printing']},{id:'money',name:'Accounts & money',routes:['transactions','receivables','expenses','cashflow']},{id:'manage',name:'Business management',routes:['inventory','reports','settings']}];
const navigationOpen={work:true,money:false,manage:false};
function navigation(){
 const link=n=>`<a href="#${n}" class="${route===n?'active':''}" ${route===n?'aria-current="page"':''}>${icon(n)}<span>${labels[n]}</span></a>`;
 $('#nav').innerHTML=link('dashboard')+navigationGroups.map(group=>{const names=group.routes.filter(n=>!['settings','printing'].includes(n)||state.role==='owner');return `<details class="nav-group" data-group="${group.id}" ${navigationOpen[group.id]||names.includes(route)?'open':''}><summary>${group.name}</summary>${names.map(link).join('')}</details>`;}).join('');
 $$('.nav-group').forEach(group=>group.addEventListener('toggle',()=>{navigationOpen[group.dataset.group]=group.open;}));
 $('#breadcrumb').textContent='Workspace / '+(labels[route]||'Overview');
}
async function navigate(){route=location.hash.slice(1)||'dashboard';if(!labels[route]||(['settings','printing'].includes(route)&&state.role!=='owner'))route='dashboard';navigation();$('.sidebar').classList.remove('open');window.DigitXReact?.unmount();const seq=++renderSequence;if(window.DigitXReact&&['dashboard','billing','customers'].includes(route)){window.DigitXReact.mount(route,state,{api,refresh:async()=>{await reload();return state;},toast,statement,reminder,clearOrder:()=>{selectedOrder=null;},deleteCustomer:id=>deleteRecord('customers',id).catch(e=>toast(e.message))},selectedOrder);return;}try{let html;if(route==='dashboard')html=dashboardView();else if(route==='billing')html=billingView();else if(route==='files'){await filesView();return;}else if(route==='printing'){await printingView();return;}else if(route==='transactions'){html=head('Transactions','Complete customer ledger, including bills, payments, refunds and running balances.',state.role==='owner'?btn('recycle-bin','Recycle Bin')+'<a class="secondary" href="/api/export/transactions.csv">Export CSV</a>':'')+'<div id="billing-area"></div>';}else if(route==='customers')html=customersView();else if(route==='receivables')html=receivablesView();else if(route==='reports')html=reportsView();else{const data=await api({'orders':'/api/orders','expenses':'/api/expenses','inventory':'/api/inventory','cashflow':'/api/cashflow','settings':'/api/users'}[route]);if(seq!==renderSequence)return;html=({orders:ordersView,expenses:expensesView,inventory:inventoryView,cashflow:cashflowView,settings:settingsView}[route])(data);}if(seq!==renderSequence)return;$('#content').innerHTML=html;bindView();if(route==='transactions')await ledgerView();}catch(error){if(seq===renderSequence)$('#content').innerHTML=head('Could not open this page',esc(error.message))+btn('refresh','Try again');}}
function stat(title,value,subtitle,featured=false,which='dashboard'){return `<article class="stat-card ${featured?'featured':''}"><span class="stat-title">${title}</span><span class="stat-icon">${icon(which)}</span><strong>${value}</strong><small>${subtitle}</small></article>`;}
function chart(monthly,series){const width=650,height=220,left=53,top=14,bottom=32,data=monthly.slice(-8);const max=Math.max(100,...data.flatMap(m=>series.map(s=>m[s.key]))),min=Math.min(0,...data.flatMap(m=>series.map(s=>m[s.key]))),range=max-min||1;const y=n=>top+(max-n)/range*(height-top-bottom);let out='';for(let i=0;i<=4;i++){const val=min+range*i/4,yy=y(val);out+=`<line x1="${left}" x2="${width-8}" y1="${yy}" y2="${yy}" stroke="#e9efed"/><text x="${left-9}" y="${yy+3}" text-anchor="end">${(val/100).toLocaleString('en',{maximumFractionDigits:0})}</text>`;}const spacing=(width-left-16)/Math.max(data.length,1);data.forEach((m,i)=>{const x=left+i*spacing+spacing/2;out+=`<text x="${x}" y="${height-9}" text-anchor="middle">${esc(new Date(m.month+'-01T12:00:00').toLocaleDateString('en',{month:'short'}))}</text>`;series.forEach((s,j)=>{const val=m[s.key],yy=y(val),zero=y(0);const bx=x+(j-(series.length-1)/2)*19;out+=`<rect x="${bx-7}" y="${Math.min(yy,zero)}" width="14" height="${Math.max(Math.abs(yy-zero),1)}" rx="3" fill="${s.color}"><title>${esc(m.month+' '+s.label+': '+money(val))}</title></rect>`;});});return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Monthly ${esc(series.map(s=>s.label).join(' and '))} chart">${out}</svg><div class="legend">${series.map(s=>`<span>${s.label}</span>`).join('')}</div>`;}
function dashboardView(){const d=state.dashboard,t=d.totals,month=d.monthly.find(m=>m.month===selectedPeriod),v=month||t,period=month?new Date(month.month+'-01T12:00:00').toLocaleDateString('en',{month:'long',year:'numeric'}):'All time';const owing=d.receivables.slice(0,5);return head('A clearer view of your business.','Sales, collections, and customer relationships — all in one place.',`<select id="dashboard-period" class="period"><option value="">All time</option>${d.monthly.slice().reverse().map(m=>`<option ${selectedPeriod===m.month?'selected':''} value="${m.month}">${m.month}</option>`).join('')}</select>`)+`<div class="stats-grid">${stat('Total sales',money(v.sales),period+' · Bills less refunds',true,'billing')}${stat('Cash collected',money(v.collected),period+' · Customer payments',false,'cashflow')}${stat('Customer receivables',money(t.receivables),`${t.owing} customers · All time`,false,'receivables')}${stat('Net profit'+(t.missing_cost?' *':''),money(v.net_profit),period+' · After operating expenses',false,'reports')}</div>${t.missing_cost?`<div class="notice">${t.missing_cost} jobs have unrecorded production costs. Profit is provisional. Add missing costs from the invoice ledger. Customer credits of ${money(t.credits)} are tracked separately from ${money(t.receivables)} in receivables.</div>`:''}<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Business performance</h2><small>Monthly sales and collections · BDT</small></div>${badge('Last 8 months')}</div>${chart(d.monthly,[{key:'sales',label:'Sales',color:'#087f76'},{key:'collected',label:'Collected',color:'#b7ddd1'}])}<div class="metric-row"><span>Gross profit<strong>${money(v.gross_profit)}</strong></span><span>Operating expenses<strong>${money(v.expenses)}</strong></span><span>Production cost<strong>${money(v.cost)}</strong></span><span>Orders<strong>${v.orders}</strong></span></div></section><section class="panel"><div class="panel-head"><div><h2>Your business at a glance</h2><small>Customer relationships · All time</small></div>${icon('customers')}</div><div class="mini-grid"><div class="mini-metric">Customers<strong>${t.customers}</strong></div><div class="mini-metric">Active<strong>${t.active}</strong></div><div class="mini-metric">VIP customers<strong>${t.vip}</strong></div><div class="mini-metric">Repeat customers<strong>${t.repeat}</strong></div><div class="mini-metric">Online requests<strong>${d.new_orders}</strong></div><div class="mini-metric">Over credit limit<strong>${t.over_limit}</strong></div></div><div class="metric-row"><span>Average order<strong>${money(t.orders?t.sales/t.orders:0)}</strong></span><span>Customer value<strong>${money(t.customers?t.sales/t.customers:0)}</strong></span></div></section></div><div class="grid-2 equal"><section class="panel"><div class="panel-head"><div><h2>Customers to follow up</h2><small>Largest outstanding balances</small></div><a class="text-link" href="#receivables">View all →</a></div>${table(['Customer','Due','Status',''],owing.map(c=>`<tr><td>${person(c)}</td><td class="money">${money(c.due)}</td><td>${badge(c.credit_status,c.due>c.limit?'red':'orange')}</td><td>${btn('reminder','↗','icon-button',`data-id="${c.id}" title="WhatsApp reminder"`)}</td></tr>`).join(''),'All accounts are clear.')}</section><section class="panel"><div class="panel-head"><div><h2>Valuable relationships</h2><small>Highest-spending repeat customers</small></div><a class="text-link" href="#customers">Customers →</a></div>${table(['Customer','Orders','Lifetime sales'],d.top_customers.slice(0,5).map(c=>`<tr><td>${person(c)}</td><td>${c.orders}</td><td class="money">${money(c.billed)}</td></tr>`).join(''))}</section></div><div class="stats-grid">${stat('Estimated cash',money(t.cash),'Recorded cash flows · All time',false,'cashflow')}${stat('Owner investment',money(t.investment),'Capital introduced · All time',false,'expenses')}${stat('Owner withdrawals',money(t.withdrawal),'Separate from expenses',false,'expenses')}${stat('Net ledger due',money(t.net_due),'Receivables less customer credits',false,'receivables')}</div>`;}
function billingView(){return head('A faster counter.','Create an invoice in seconds. Record later payments without creating new sales.',btn('payment','＋ Receive payment')+btn('customer-add','＋ Customer'))+`<div class="tab-strip"><button class="active" data-action="billing-mode" data-mode="new">New invoice</button><button data-action="billing-mode" data-mode="ledger">Transaction ledger</button></div><div id="billing-area"><form id="invoice-form"><div class="billing-layout"><section class="panel"><div class="bill-section"><h3>01 · Customer & order</h3><div class="form-grid three">${customerField(selectedOrder?.customer_id||'')}${dateField()}<label>Service category<select name="category">${opt(state.categories,selectedOrder?.service||'Document Printing')}</select></label></div><div id="customer-context" class="customer-context hidden"></div>${selectedOrder?`<div class="notice info">Billing online order ORD-${String(selectedOrder.id).padStart(5,'0')} · ${esc(selectedOrder.name)}. Select or add the correct customer first.</div>`:''}</div><div class="bill-section"><div class="panel-head"><h3>02 · Print items</h3><select id="service-preset"><option value="">Add a saved service…</option>${state.services.map(s=>`<option value="${s.id}">${esc(s.name)} · ${money(s.price)}/${esc(s.unit)}</option>`).join('')}</select></div><div class="item-line item-head"><span>Description</span><span>Qty</span><span>Price/unit</span><span>Cost/unit</span><span></span></div><div id="invoice-items">${itemLine({description:selectedOrder?.details||'',quantity:selectedOrder?.quantity||1})}</div>${btn('item-add','＋ Add item')}<small class="keyboard">Leave cost blank if unknown; enter 0 only if confirmed.</small></div><div class="form-grid">${field('Due date','due_date',addDays(state.today,Number(state.settings.credit_days||7)),'date')}${field('Job / invoice number (optional)','number','') }<label class="full">Internal notes<textarea name="notes" placeholder="Job instructions, delivery, or a reference…"></textarea></label></div></section><aside class="panel billing-summary"><span class="eyebrow">INVOICE SUMMARY</span><h3>Bill total</h3><strong id="bill-total">৳0.00</strong><dl><dt>Recorded production cost</dt><dd id="bill-cost">৳0.00</dd><dt>Gross profit <span id="cost-asterisk">*</span></dt><dd id="bill-profit">৳0.00</dd></dl><label>Paid now<input name="paid" type="number" min="0" step="0.01" value="0" id="bill-paid"></label><div style="margin-top:15px">${methodField()}</div><div class="customer-context">Remaining on this invoice <b id="bill-due">৳0.00</b></div><button class="primary wide" type="submit">Create invoice & preview →</button><small>The invoice opens instantly for printing or saving as PDF. Payment does not determine profit.</small></aside></div></form></div>`;}
function itemLine(item={}){return `<div class="item-group"><div class="item-line"><input class="item-desc" placeholder="e.g. A4 black & white" value="${esc(item.description||'')}" required maxlength="180"><input class="item-qty" type="number" min="0.001" step="0.001" value="${esc(item.quantity||1)}" required><input class="item-price" type="number" min="0" step="0.01" value="${esc(item.price??'')}" placeholder="0.00" required><input class="item-cost" type="number" min="0" step="0.01" value="${esc(item.cost??'')}" placeholder="Unknown">${btn('item-remove','×','icon-button','aria-label="Remove invoice item"')}</div><div class="line-total">Line total: ${money(Math.round(Number(item.quantity||1)*Number(item.price||0)*100))}</div></div>`;}
function addDays(day,n){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);}
function calcBill(){if(!$('#invoice-form'))return;let total=0,cost=0,unknown=false;$$('.item-group').forEach(group=>{const qty=Number($('.item-qty',group).value),price=Math.round(Number($('.item-price',group).value)*100),line=Math.round(qty*price);total+=line;cost+=Math.round(qty*Math.round(Number($('.item-cost',group).value)*100));unknown||=$('.item-cost',group).value==='';$('.line-total',group).textContent='Line total: '+money(line);});$('#bill-total').textContent=money(total);$('#bill-cost').textContent=money(cost);$('#bill-profit').textContent=money(total-cost);$('#bill-due').textContent=money(total-Math.round(Number($('#bill-paid').value)*100));$('#cost-asterisk').textContent=unknown?'*':'';}
function contextCustomer(){const input=$('[name=customer_id]','#invoice-form');if(!input)return;let c=state.customers.find(c=>c.id===input.value);if(!c&&/^8801\d{9}$/.test(normalizePhone(input.value))){const matches=state.customers.filter(c=>normalizePhone(c.phone)===normalizePhone(input.value));if(matches.length===1){c=matches[0];input.value=c.id;}}const box=$('#customer-context');box.classList.toggle('hidden',!c);if(c)box.innerHTML=`${esc(c.id)} · ${esc(c.name)} · Account balance <b>${money(c.due)}</b> · ${badge(c.credit_status,c.due>c.limit?'red':'green')} · ${c.orders} previous orders`;}
function customersView(){return head('Every customer. One history.','Search names, numbers, institutions, or permanent customer IDs.',btn('customer-add','＋ Add customer','primary'))+`<section class="panel"><div class="toolbar"><input id="customer-search" type="search" placeholder="Search customers…"><select id="customer-filter">${opt(['All customers','With dues','VIP customers','Repeat customers','Inactive 30+ days','Inactive 60+ days','Inactive 90+ days'])}</select><span class="count" id="customer-count">${state.customers.length} customers</span></div><div id="customer-table">${customerTable(state.customers)}</div></section>`;}
function customerTable(customers){return table(['Customer','Contact / institution','Orders','Billed','Paid','Due / credit','Last order',''],customers.map(c=>`<tr><td>${person(c)}</td><td>${esc(c.phone||'No phone')}<small>${esc(c.institution||c.type)}</small></td><td>${c.orders}</td><td class="money">${money(c.billed)}</td><td>${money(c.paid)}</td><td>${badge(money(c.due),c.due>c.limit?'red':c.due>0?'orange':'green')}</td><td>${esc(c.last_order||'No orders')}</td><td>${btn('statement','Statement','secondary',`data-id="${c.id}"`)}${deleteButton('customers',c.id)}</td></tr>`).join(''));}
function filterCustomers(){const q=$('#customer-search').value.toLowerCase(),filter=$('#customer-filter').value;const found=state.customers.filter(c=>[c.name,c.id,c.phone,c.institution].some(v=>String(v||'').toLowerCase().includes(q))).filter(c=>filter==='With dues'?c.due>0:filter==='VIP customers'?c.vip:filter==='Repeat customers'?c.orders>1:filter.startsWith('Inactive')?c.inactive_days>=parseInt(filter.split(' ')[1]):true);$('#customer-table').innerHTML=customerTable(found);$('#customer-count').textContent=found.length+' customers';}
function receivablesView(){const t=state.dashboard.totals;return head('Follow up with confidence.','Customer balances use the complete ledger. Unlinked payments settle the oldest debt; invoice-linked payments settle the selected invoice.',btn('payment','＋ Receive payment','primary'))+`<div class="stats-grid">${stat('Outstanding receivables',money(t.receivables),t.owing+' customers',true,'receivables')}${stat('Over credit limit',String(t.over_limit),'Zero limits are preserved',false,'customers')}${stat('Customer credits',money(t.credits),'Advance / excess payments',false,'cashflow')}${stat('Net ledger due',money(t.net_due),'Receivables less credits',false,'reports')}</div><section class="panel"><div class="panel-head"><h2>Customer receivables</h2>${badge('FIFO aging')}</div>${table(['Customer','WhatsApp','Due','Oldest due date','Overdue days','Limit','Aging',''],state.dashboard.receivables.map(c=>`<tr><td>${person(c)}</td><td>${esc(c.phone||'Add contact')}</td><td class="money">${money(c.due)}</td><td>${esc(c.oldest_due||'Date needed')}</td><td>${c.days_overdue??'—'}</td><td>${money(c.limit)}</td><td>${Object.entries(c.aging).map(([band,amount])=>badge(band+' · '+money(amount),band.includes('90')?'red':band==='Current'?'green':'orange')).join(' ')}</td><td>${btn('reminder','WhatsApp ↗','secondary',`data-id="${c.id}"`)}</td></tr>`).join(''),'All accounts are clear.')}</section>`;}
function ordersView(orders){return head('From upload to collection.','Review documents, confirm a quote, and move each job through your print queue.',btn('order-qr','Share order link & QR','primary'))+`<div class="toolbar"><input id="order-search" type="search" placeholder="Search name or order…"><select id="order-filter">${opt(['All statuses','New','Quoted','In Progress','Ready','Delivered','Cancelled'])}</select><span class="count">${orders.length} requests</span></div><div id="order-list">${orders.map(order=>orderCard(order)).join('')||'<section class="panel empty">Share your order QR to receive the first online request.</section>'}</div>`;}
function orderCard(o){let options={};try{options=JSON.parse(o.options);}catch{}return `<section class="panel order-card" data-status="${esc(o.status)}" data-search="${esc((o.name+' '+o.phone+' ORD-'+String(o.id).padStart(5,'0')).toLowerCase())}"><div class="order-card-head"><div><span class="eyebrow">ORD-${String(o.id).padStart(5,'0')} · ${esc(o.created.slice(0,10))}</span><h3>${esc(o.name)} <small>· ${esc(o.phone)}</small></h3></div>${badge(o.status,o.status==='Ready'?'green':o.status==='New'?'orange':'blue')}</div><p><b>${esc(o.service)}</b> · ${o.quantity} ${o.service==='Stamp Size Photo'?'photos':'copies'} · ${esc(['paper','color','sides','binding','deadline'].map(k=>options[k]).filter(Boolean).join(' / ')) + (options.bw_pages!=null ? ' · '+esc(options.bw_pages)+' B&W + '+esc(options.color_pages)+' color pages/copy' : options.pages ? ' · '+esc(options.pages)+' pages/copy' : '')}</p><p>${esc(o.details)}</p><div>${o.files.map(f=>f.deleted_at ? `<span class="file-link muted">${esc(f.name)} · Deleted under retention policy</span>` : `<a href="/api/files/${f.id}" class="file-link">↓ ${esc(f.name)} · ${(f.size/1024).toFixed(0)} KB</a>${deleteButton('files',f.id)}`).join('')}</div><div class="head-actions">${btn('order-edit','Update status / notes','secondary',`data-id="${o.id}"`)}${state.role==='owner'?btn('order-details-edit','Edit order','secondary',`data-id="${o.id}"`)+deleteButton('orders',o.id):''}${!o.invoice_id&&o.status!=='Cancelled'?btn('order-confirm','Review price & create invoice','primary',`data-id="${o.id}"`):''}<a class="text-link" href="/track/${esc(o.token)}" target="_blank" rel="noopener">Tracking page ↗</a>${o.matched_customer_id?badge('Customer '+o.matched_customer_id,'blue'):''}${options.minimum_quote!=null?badge('Minimum '+money(options.minimum_quote),'green'):''}${o.quote!==null?badge('Confirmed '+money(o.quote)):''}${o.invoice_id?`<a class="secondary" href="${esc(o.invoice_url)}" target="_blank" rel="noopener">View invoice</a>`:''}</div></section>`;}
function expensesView(entries){return head('A clear separation of money.','Operating expenses reduce profit. Investments and owner withdrawals affect capital and cash.',btn('expense-add','＋ Record entry','primary'))+`<div class="notice info">Materials used in a job belong in its production cost. Use Stock Purchase for inventory bought now and consumed later; it reduces cash, and job costs reduce profit as stock is used. Avoid recording the same materials as both an operating expense and a job cost.</div><section class="panel"><div class="toolbar"><input id="expense-search" type="search" placeholder="Search entries…"><select id="expense-filter">${opt(['All types','Expense','Investment','Owner Withdrawal','Stock Purchase'])}</select><span class="count">${entries.length} entries</span></div>${table(['Date','Type','Category','Description','Amount','Method','Entered by','Edit'],entries.map(e=>`<tr class="expense-row" data-kind="${esc(e.kind)}" data-search="${esc((e.description+' '+e.category+' '+e.vendor).toLowerCase())}"><td>${e.date}</td><td>${badge(e.kind,e.kind==='Investment'?'green':e.kind==='Owner Withdrawal'?'orange':'blue')}</td><td>${esc(e.category)}</td><td>${esc(e.description||'—')}<small>${esc(e.notes)}</small></td><td class="money">${money(e.amount)}</td><td>${esc(e.method)}</td><td>${esc(e.actor)}</td><td>${state.role==='owner'?btn('expense-edit','Edit','secondary',`data-id="${e.id}"`)+deleteButton('expenses',e.id):''}</td></tr>`).join(''))}</section>`;}
function inventoryView(data){return head('Keep the essentials in stock.','Simple stock counts, purchase movements, usage, and reorder alerts.',state.role==='owner'?btn('inventory-add','＋ Add material','primary'):'')+`<div class="notice info">Stock use updates quantities. Record the consumed production cost on the relevant invoice; it is not automatically inferred from a stock movement.</div><section class="panel"><div class="panel-head"><h2>Materials</h2></div>${table(['Material','Current stock','Unit','Reorder level','Supplier','Status',''],data.items.map(i=>`<tr><td><b>${esc(i.name)}</b></td><td class="money">${i.stock}</td><td>${esc(i.unit)}</td><td>${i.reorder}</td><td>${esc(i.supplier)}</td><td>${badge(i.stock<=i.reorder?'Reorder':'In stock',i.stock<=i.reorder?'orange':'green')}</td><td>${btn('stock-move','Stock movement','secondary',`data-id="${i.id}"`)}${state.role==='owner'?btn('inventory-edit','Edit','secondary',`data-id="${i.id}"`)+deleteButton('inventory',i.id):''}</td></tr>`).join(''),'Add A4 paper, toner, binding materials, or other supplies.')}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Recent movements</h2></div>${table(['Date','Material','Type','Quantity','Unit cost','Notes','Edit'],data.movements.map(m=>`<tr><td>${m.date}</td><td>${esc(m.name)}</td><td>${badge(m.kind)}</td><td>${m.quantity}</td><td>${money(m.unit_cost)}</td><td>${esc(m.notes)}</td><td>${state.role==='owner'?btn('movement-edit','Edit','secondary',`data-id="${m.id}"`)+deleteButton('movements',m.id):''}</td></tr>`).join(''))}</section>`;}
function cashflowView(days){const t=state.dashboard.totals;return head('Sales are a promise. Cash is movement.','Daily recorded receipts and payments, including capital and stock purchases.')+`<div class="stats-grid">${stat('Estimated cash balance',money(t.cash),'Includes configured opening cash',true,'cashflow')}${stat('Customer collections',money(t.collected),'Net of cash refunds',false,'billing')}${stat('Net capital introduced',money(t.investment-t.withdrawal),'Investments less withdrawals',false,'expenses')}${stat('Stock purchases',money(t.stock_purchase),'Cash spent on inventory',false,'inventory')}</div><section class="panel">${table(['Date','Collection','Investment','Expenses','Withdrawals','Stock purchases','Net movement','Running cash'],days.slice().reverse().map(d=>`<tr><td>${d.date}</td><td>${money(d.collection)}</td><td>${money(d.investment)}</td><td>${money(d.expense)}</td><td>${money(d.withdrawal)}</td><td>${money(d.stock)}</td><td>${badge(money(d.net),d.net>=0?'green':'red')}</td><td class="money">${money(d.balance)}</td></tr>`).join(''))}</section><p class="muted">Cash balance reflects recorded movements, not a bank reconciliation. Production cost affects profit; record its purchase cash flow separately, without duplicating an operating expense.</p>`;}
function reportsView(){const t=state.dashboard.totals,months=state.dashboard.monthly,known=state.customers.filter(c=>c.joined),newCount=known.filter(c=>c.joined.slice(0,7)===state.today.slice(0,7)).length,buyers=state.customers.filter(c=>c.orders>0).length;const bands={};state.dashboard.receivables.forEach(c=>Object.entries(c.aging).forEach(([k,v])=>bands[k]=(bands[k]||0)+v));return head('Find the patterns that matter.','Monthly performance, customer retention, profitability, and receivable aging.',state.role==='owner'?`<a href="/api/export/transactions.csv" class="secondary">Export ledger CSV</a>`:'')+`<div class="stats-grid">${stat('Repeat customer rate',(buyers?t.repeat/buyers*100:0).toFixed(1)+'%',t.repeat+' repeat / '+buyers+' purchasing customers',false,'customers')}${stat('Gross margin'+(t.missing_cost?' *':''),(t.sales?t.gross_profit/t.sales*100:0).toFixed(1)+'%','Profit / sales',false,'reports')}${stat('New customers this month',known.length===state.customers.length?String(newCount):newCount+' known',state.customers.length-known.length+' joining dates unavailable',false,'customers')}${stat('Estimated business capital',money(t.capital),'Net investment + retained profit',false,'expenses')}</div><div class="grid-2 equal"><section class="panel"><div class="panel-head"><h2>Profit and expenses</h2></div>${chart(months,[{key:'net_profit',label:'Net profit',color:'#087f76'},{key:'expenses',label:'Expenses',color:'#dc8b37'}])}</section><section class="panel"><div class="panel-head"><h2>Receivable aging</h2></div><div class="bar-list">${['Current','1–7 days','8–30 days','31–60 days','61–90 days','90+ days','Date needed'].map(b=>`<div><span>${b}</span><i style="width:${Math.max(1,(bands[b]||0)/Math.max(1,t.receivables)*60)}%"></i><b>${money(bands[b]||0)}</b></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Monthly performance</h2><small>Due change is monthly net billing less collections, plus balance adjustments; it is not the closing receivable balance.</small></div></div>${table(['Month','Sales','Collection','Due change','Production cost','Gross profit','Expenses','Net profit','Orders','Net cash'],months.slice().reverse().map(m=>`<tr><td>${m.month}</td><td>${money(m.sales)}</td><td>${money(m.collected)}</td><td>${money(m.due_change)}</td><td>${money(m.cost)}</td><td>${money(m.gross_profit)}</td><td>${money(m.expenses)}</td><td class="money">${money(m.net_profit)}</td><td>${m.orders}</td><td>${money(m.net_cash)}</td></tr>`).join(''))}</section><div class="grid-2 equal" style="margin-top:20px"><section class="panel"><h2>Most frequent customers</h2>${table(['Customer','Orders','Sales'],state.customers.slice().sort((a,b)=>b.orders-a.orders).slice(0,8).map(c=>`<tr><td>${person(c)}</td><td>${c.orders}</td><td>${money(c.billed)}</td></tr>`).join(''))}</section><section class="panel"><h2>Highest profit customers ${t.missing_cost?'*':''}</h2>${table(['Customer','Recorded profit','Unknown costs'],state.customers.slice().sort((a,b)=>b.profit-a.profit).slice(0,8).map(c=>`<tr><td>${person(c)}</td><td>${money(c.profit)}</td><td>${c.missing_cost} jobs</td></tr>`).join(''))}</section></div>`;}
function settingsView(users){const s=state.settings;return head('Make DigitXBD your own.','Business identity, payment QR, saved prices, permissions, and backups.')+`<form id="settings-form"><section class="panel setting-section"><h3>Business details</h3><div class="form-grid three">${field('Business name','business_name',s.business_name)}${field('Owner name','owner_name',s.owner_name)}${field('Business WhatsApp','phone',s.phone)}${field('Payment number','payment_number',s.payment_number)}${field('Address','address',s.address)}${field('Public URL','public_url',s.public_url||new URL(state.order_url).origin,'url')}</div><label>Invoice footer<textarea name="invoice_footer">${esc(s.invoice_footer)}</textarea></label></section><section class="panel setting-section"><h3>Credit & analytics</h3><div class="form-grid three">${field('VIP sales threshold (৳)','vip_spend',s.vip_spend,'number','min="0" step="0.01" required')}${field('VIP order threshold','vip_orders',s.vip_orders,'number','min="1" required')}${field('Default credit limit (৳)','credit_limit',s.credit_limit,'number','min="0" step="0.01" required')}${field('Default credit period (days)','credit_days',s.credit_days,'number','min="1" required')}${field('Opening recorded cash (৳)','opening_cash',s.opening_cash,'number','step="0.01" required')}</div></section><section class="panel setting-section"><h3>Merchant Bangla QR</h3><p class="muted">Upload the original QR image from your merchant account. This exact image will appear on every invoice; no string or QR regeneration is needed.</p><label>Original merchant QR image<input type="file" id="merchant-qr-image" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP · maximum 8 MB. Upload saves immediately and preserves the original image.</small></label>${s.merchant_qr_image?`<img class="merchant-image-preview" src="/merchant-qr/${esc(s.merchant_qr_image)}" alt="Saved original merchant QR"><div class="head-actions">${btn('merchant-image-remove','Remove image','danger-button')}${btn('merchant-image-history','Previous images')}</div>`:`<p class="muted">${s.merchant_qr?'An older decoded QR is still available until you upload your original image.':'No original image saved yet.'}</p>${btn('merchant-image-history','Previous images')}`}</section><section class="panel setting-section"><h3>Uploaded file retention</h3><div class="form-grid">${field('Delete after (days)','file_retention_days',s.file_retention_days,'number','min="1" max="3650" required')}<label>Count from<select name="file_retention_basis"><option value="completed" ${s.file_retention_basis==='completed'?'selected':''}>Delivery or cancellation</option><option value="upload" ${s.file_retention_basis==='upload'?'selected':''}>Upload date</option></select></label></div><small>Cleanup runs hourly while DigitXBD is running. Order records and customer balances stay available. Downloaded backups keep their own file copies.</small></section><section class="panel setting-section"><h3>WhatsApp due reminder</h3><label>Message template<textarea name="reminder_template">${esc(s.reminder_template)}</textarea></label><small>Use {name}, {due}, and {statement_url}. A private statement link is included automatically. You review and send each reminder in WhatsApp.</small></section><button class="primary" type="submit">Save settings</button></form><div class="grid-2 equal" style="margin-top:25px"><section class="panel"><div class="panel-head"><h2>Saved service prices</h2>${btn('service-add','＋ Service')}</div>${table(['Service','Price','Cost',''],state.services.map(s=>`<tr><td>${esc(s.name)}<small>per ${esc(s.unit)}</small></td><td>${money(s.price)}</td><td>${money(s.cost)}</td><td>${btn('service-edit','Edit','secondary',`data-id="${s.id}"`)+deleteButton('services',s.id)}</td></tr>`).join(''),'Add your actual prices for one-click billing.')}</section><section class="panel"><div class="panel-head"><h2>Team access</h2>${btn('user-add','＋ User')}</div>${table(['User','Role','Status',''],users.map(u=>`<tr><td>${esc(u.username)}</td><td>${badge(u.role)}</td><td>${u.active?'Active':'Disabled'}</td><td>${btn('user-edit','Manage','secondary',`data-id="${u.id}" data-active="${u.active}"`)}${deleteButton('users',u.id)}</td></tr>`).join(''))}</section></div><section class="panel"><div class="panel-head"><h2>Your data, under your control.</h2>${btn('audit','View audit trail')}${btn('recycle-bin','Recycle Bin')}</div><p>Download a full backup containing the database and uploaded files. Keep a copy outside the Docker volume.</p><div class="head-actions"><a class="primary" href="/api/backup">Download full backup</a><a class="secondary" href="/api/export/customers.csv">Customers CSV</a><a class="secondary" href="/api/export/expenses.csv">Expenses CSV</a></div><small>CSV monetary fields are in paisa (100 paisa = ৳1), stated in the filenames. See README for backup restoration and deployment.</small></section>`;}

function bindView(){if(route==='billing'){const form=$('#invoice-form');form?.addEventListener('input',()=>{calcBill();contextCustomer();});form?.addEventListener('submit',submitInvoice);$('#service-preset')?.addEventListener('change',e=>{const preset=state.services.find(s=>s.id===Number(e.target.value));if(!preset)return;$('#invoice-items').insertAdjacentHTML('beforeend',itemLine({description:preset.name,quantity:1,price:numeric(preset.price),cost:numeric(preset.cost)}));const blank=$$('.item-group').find(group=>!$('.item-desc',group).value&&!$('.item-price',group).value);if(blank&&$$('.item-group').length>1)blank.remove();e.target.value='';calcBill();});calcBill();contextCustomer();}$('#dashboard-period')?.addEventListener('change',e=>{selectedPeriod=e.target.value;navigate();});$('#customer-search')?.addEventListener('input',filterCustomers);$('#customer-filter')?.addEventListener('change',filterCustomers);const filters=(search,select,row,match)=>{const filter=()=>{const q=$(search).value.toLowerCase(),val=$(select).value;$$(row).forEach(el=>el.classList.toggle('hidden',!el.dataset.search.includes(q)||(!val.startsWith('All')&&el.dataset[match]!==val)));};$(search)?.addEventListener('input',filter);$(select)?.addEventListener('change',filter);};if(route==='orders')filters('#order-search','#order-filter','.order-card','status');if(route==='expenses')filters('#expense-search','#expense-filter','.expense-row','kind');$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=$('[type=submit]',e.target);button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if($('[name=dynamic_qr_enabled]',e.target))data.dynamic_qr_enabled=$('[name=dynamic_qr_enabled]',e.target).checked?'1':'0';await api('/api/settings','PUT',data);await reload();toast('Settings saved.');}catch(error){toast(error.message);}finally{button.disabled=false;}});}
async function submitInvoice(e){e.preventDefault();const button=$('[type=submit]',e.target);button.disabled=true;const data=Object.fromEntries(new FormData(e.target));data.kind='Invoice';data.request_key=invoiceKey;data.items=$$('.item-group').map(group=>({description:$('.item-desc',group).value,quantity:$('.item-qty',group).value,price:$('.item-price',group).value,cost:$('.item-cost',group).value}));if(selectedOrder)data.order_id=selectedOrder.id;try{const saved=await api('/api/transactions','POST',data);invoiceKey=crypto.randomUUID();selectedOrder=null;await reload();modal('Invoice created',`<div class="notice info">Saved successfully. Customer balance and profit have updated.</div><div class="head-actions"><a class="primary" href="${esc(saved.invoice_url)}" target="_blank" rel="noopener">Open invoice / Print / PDF ↗</a>${btn('new-invoice','Create another invoice')}</div>`);navigate();}catch(error){toast(error.message);}finally{button.disabled=false;}}
function customerAdd(){modal('Add a repeat customer',`<form><div class="form-grid">${field('Customer name','name',selectedOrder?.name||'','text','required maxlength="120"')}${field('WhatsApp / mobile','phone',selectedOrder?.phone||'','tel') }<label>Customer type<select name="type">${opt(['Student','Regular','Retail','Teacher','Institution','Corporate','Other'])}</select></label>${field('Institution / university','institution')}${field('Department','department')}${field('Alternative contact','alternate')}<label>Status<select name="status">${opt(['Active','VIP','Credit','Inactive'])}</select></label>${field('Joined date','joined',state.today,'date')}${field('Credit limit (৳; blank uses default)','credit_limit','','number','min="0" step="0.01"')}${state.role==='owner'?field('Opening due / credit (৳)','opening','0','number','step="0.01"')+field('Opening due date (if known)','opening_date','','date'):''}<label class="full">Notes<textarea name="notes"></textarea></label></div><div class="modal-footer"><button class="primary" type="submit">Save customer</button></div></form>`,async data=>{const c=await api('/api/customers','POST',data);closeModal();await reload();await navigate();if(route==='billing'){$('[name=customer_id]','#invoice-form').value=c.id;contextCustomer();}toast('Customer created: '+c.id);});}
async function statement(cid){const data=await api('/api/customers/'+encodeURIComponent(cid)+'/statement'),c=data.customer;modal(esc(c.name)+' · Account statement',`<span class="eyebrow">${esc(c.id)} · ${esc(c.phone||'No contact')}</span><div class="stats-grid">${stat('Billed',money(c.billed),'Lifetime')}${stat('Paid',money(c.paid),'Net collection')}${stat('Current due',money(c.due),'Including opening balance')}${stat('Gross profit'+(c.missing_cost?' *':''),money(c.profit),c.missing_cost+' unknown costs')}</div><div class="notice info">Opening due / credit: ${money(c.opening)} · Opening date: ${esc(c.opening_date||'Not available')} · ${c.orders} orders · Last order: ${esc(c.last_order||'—')}</div>${table(['Date','Type / job','Description','Bill / adjustment','Payment','Balance','Method'],data.history.map(t=>`<tr><td>${t.date}</td><td>${badge(t.kind)}<small>${esc(t.number)}</small></td><td>${esc(t.description)}</td><td>${money(t.bill)}</td><td>${money(t.paid)}</td><td class="money">${money(t.balance)}</td><td>${t.paid?esc(t.method):""}</td></tr>`).join(''))}<div class="modal-footer no-print">${btn('print','Print statement')}${state.role==='owner'?btn('customer-edit','Edit customer','secondary',`data-id="${c.id}"`):''}${btn('payment','Receive payment','primary',`data-id="${c.id}"`)}</div>`);}
function customerEdit(cid){const c=state.customers.find(c=>c.id===cid);if(!c)return;closeModal();modal('Edit customer · '+esc(c.id),`<form><div class="form-grid">${field('Name','name',c.name,'text','required')}${field('Phone','phone',c.phone)}<label>Type<select name="type">${opt(['Student','Regular','Retail','Teacher','Institution','Corporate','Other'],c.type)}</select></label>${field('Institution','institution',c.institution)}${field('Department','department',c.department)}${field('Alternative contact','alternate',c.alternate)}${field('Opening due date (if known)','opening_date',c.opening_date||'','date')}<label>Status<select name="status">${opt(['Active','VIP','Credit','Inactive'],c.status)}</select></label>${field('Joined date','joined',c.joined||'','date')}${field('Opening due / credit (৳)','opening',numeric(c.opening),'number','step="0.01"')}${field('Credit limit (৳)','credit_limit',c.credit_limit===null?'':numeric(c.credit_limit),'number','min="0" step="0.01"')}<label class="full">Notes<textarea name="notes">${esc(c.notes)}</textarea></label></div><small>Admin changes recalculate balances and are recorded in the audit trail.</small><div class="modal-footer"><button class="primary" type="submit">Save changes</button></div></form>`,async data=>{await api('/api/customers/'+cid,'PUT',data);closeModal();await reload();navigate();toast('Customer updated.');});}
function paymentModal(cid='',related=''){if($('#modal').open)closeModal();const key=crypto.randomUUID();modal('Receive a customer payment',`<form><div class="notice info">A later payment reduces old dues and increases collection. It creates no new sale or profit. Leave the invoice reference blank for an account payment.</div><div class="form-grid">${customerField(cid)}${dateField()}${field('Amount received (৳)','paid','','number','min="0.01" step="0.01" required')}${methodField()}${field('Invoice ledger ID (optional)','related_id',related,'number','min="1"')}${field('Description','description','Payment against customer dues')}<label class="full">Notes<textarea name="notes"></textarea></label></div><div class="modal-footer"><button class="primary" type="submit">Record payment</button></div></form>`,async data=>{if(!data.related_id)delete data.related_id;await api('/api/transactions','POST',{...data,kind:'Payment',request_key:key});closeModal();await reload();navigate();toast('Payment recorded.');});}
async function ledgerView(page=1,q='',kind=''){
const data=await api('/api/transactions?page='+page+'&q='+encodeURIComponent(q)+'&kind='+encodeURIComponent(kind));if(!['billing','transactions'].includes(route))return;
const wide=route==='transactions';
const headers=wide?['Transaction ID','Date','Customer ID','Customer name','Type','Invoice / job','Service category','Description','Quantity','Unit price','Bill amount','Production cost','Gross profit','Paid amount','Method','Payment status','Customer balance','Due date','Days overdue','Operator','Notes','Actions']:['Date','Ledger ID / type','Customer','Job / description','Bill','Cost','Paid','Actions'];
const body=data.rows.map(t=>{
 let items=[];try{items=JSON.parse(t.items);}catch{}
 const quantity=items.reduce((n,i)=>n+Number(i.quantity||0),0);
 const overdue=t.remaining>0&&t.due_date?Math.max(0,Math.floor((new Date(state.today+'T00:00:00Z')-new Date(t.due_date+'T00:00:00Z'))/86400000)):0;
 const status=t.kind==='Invoice'?(t.remaining===0?'Paid':t.remaining<t.bill?'Partial':'Due'):t.kind==='Payment'?'Received':t.kind;
 const actions=(state.role==='owner'?btn('transaction-edit','Edit','secondary',`data-id="${t.id}"`)+deleteButton('transactions',t.id):'')+(t.kind==='Invoice'?`<a class="text-link" href="/invoice/${esc(t.token)}" target="_blank" rel="noopener">Invoice ↗</a>${btn('payment','＋ Pay','secondary',`data-id="${t.customer_id}" data-related="${t.id}"`)}`:'');
 const cost=t.cost_known?money(t.cost):badge('Unknown','orange');
 const cells=wide?[t.id,t.date,esc(t.customer_id),esc(t.customer_name),badge(t.kind),esc(t.number),esc(t.category),esc(t.description),quantity||'—',items.length===1?money(items[0].price):items.length?'Mixed':'—',money(t.bill),cost,t.cost_known?money(['Invoice','Refund'].includes(t.kind)?t.bill-t.cost:0):'Provisional',money(t.paid),(t.kind==='Invoice'&&t.remaining>0)||!t.paid?'':esc(t.method),badge(status,overdue?'red':status==='Paid'?'green':'blue'),money(t.balance),esc(t.due_date||'—'),overdue,esc(t.actor),esc(t.notes),actions]:[t.date,t.id+' · '+badge(t.kind),esc(t.customer_name)+'<small>'+esc(t.customer_id)+'</small>',esc(t.number)+'<small>'+esc(t.description)+'</small>',money(t.bill),cost,money(t.paid),actions];
 return '<tr>'+cells.map((c,i)=>`<td data-label="${esc(headers[i])}">${c}</td>`).join('')+'</tr>';
}).join('');
$('#billing-area').innerHTML=`<section class="panel ${wide?'transactions-panel':''}"><div class="toolbar"><input id="transaction-search" type="search" placeholder="Search ID, invoice, customer or description…" value="${esc(q)}"><select id="transaction-filter">${opt(['All types','Invoice','Payment','Adjustment','Refund'],kind||'All types')}</select>${btn('ledger-search','Search')}<span class="count">${data.total} transactions</span></div>${state.role==='owner'?`<div class="head-actions" style="margin-bottom:15px">${btn('adjustment','Balance adjustment')}${btn('refund','Refund / credit note')}${btn('recycle-bin','Recycle Bin')}</div>`:''}${table(headers,body)}<div class="modal-footer">${page>1?btn('ledger-page','← Previous','secondary',`data-page="${page-1}" data-q="${esc(q)}" data-kind="${esc(kind)}"`):''}${page*100<data.total?btn('ledger-page','Next →','secondary',`data-page="${page+1}" data-q="${esc(q)}" data-kind="${esc(kind)}"`):''}</div></section>`;
$('#transaction-search').addEventListener('keydown',e=>{if(e.key==='Enter')searchLedger();});
}
function searchLedger(){ledgerView(1,$('#transaction-search').value,$('#transaction-filter').value==='All types'?'':$('#transaction-filter').value).catch(e=>toast(e.message));}
function adjustmentModal(refund=false){const key=crypto.randomUUID();modal(refund?'Refund / sales credit':'Customer balance adjustment',`<form><div class="notice info">${refund?'A refund reduces sales and customer due. Cash paid back is a separate field; reversing cost is optional and should reflect actual recovered production cost.':'An adjustment changes customer due without changing sales or profit. Positive increases due; negative reduces due. Always give a reason.'}</div><div class="form-grid">${customerField()}${dateField()}${refund?field('Original invoice ledger ID','related_id','','number','min="1" required'):''}${field(refund?'Sales refund amount (৳)':'Signed balance adjustment (৳)','amount','','number',`step="0.01" ${refund?'min="0.01"':''} required`)}${refund?field('Cash paid back to customer (৳)','paid','0','number','min="0" step="0.01"')+field('Production cost to reverse (৳)','cost_reversal','0','number','min="0" step="0.01"')+methodField():''}${field('Reason','description','','text','required')}<label class="full">Notes<textarea name="notes"></textarea></label></div><div class="modal-footer"><button class="primary" type="submit">Save ${refund?'refund':'adjustment'}</button></div></form>`,async data=>{await api('/api/transactions','POST',{...data,kind:refund?'Refund':'Adjustment',request_key:key});closeModal();await reload();await ledgerView();toast('Ledger updated.');});}
function expenseModal(){modal('Record expense or capital',`<form><div class="form-grid">${dateField()}<label>Entry type<select name="kind">${opt(state.role==='owner'?['Expense','Investment','Owner Withdrawal','Stock Purchase']:['Expense'])}</select></label><label>Category<select name="category">${opt(['Electricity','Internet','Rent','Equipment Maintenance','Delivery','Packaging','Advertising','Software','Paper','Ink','Toner','Binding Materials','Lamination Materials','Material','Other'])}</select></label>${field('Amount (৳)','amount','','number','min="0.01" step="0.01" required')}${methodField()}${field('Vendor / supplier','vendor')}${field('Description','description','','text','required')}<label class="full">Notes<textarea name="notes"></textarea></label></div><div class="modal-footer"><button class="primary" type="submit">Record entry</button></div></form>`,async data=>{await api('/api/expenses','POST',data);closeModal();await reload();navigate();toast('Entry recorded.');});}
async function reminder(cid){const data=await api('/api/reminder/'+encodeURIComponent(cid));modal('Review WhatsApp reminder',`<p>This opens WhatsApp with the message below. You send it yourself.</p><div class="notice info" style="white-space:pre-wrap">${esc(data.message)}</div><div class="modal-footer"><a class="primary" href="${esc(data.url)}" target="_blank" rel="noopener">Open WhatsApp ↗</a></div>`);}
async function orderEdit(id){const orders=await api('/api/orders'),o=orders.find(o=>o.id===Number(id));if(!o)return;modal('Update ORD-'+String(o.id).padStart(5,'0'),`<form><div class="form-grid"><label>Status<select name="status">${opt(['New','Quoted','In Progress','Ready','Delivered','Cancelled'],o.status)}</select></label>${field('Confirmed quote (৳)','quote',o.quote===null?'':numeric(o.quote),'number','min="0" step="0.01" '+(o.invoice_id?'readonly':''))}<label class="full">Internal staff notes<textarea name="staff_notes">${esc(o.staff_notes)}</textarea></label></div><div class="modal-footer"><button class="primary" type="submit">Update order</button></div></form>`,async data=>{await api('/api/orders/'+id,'PUT',data);closeModal();await reload();navigate();toast('Order updated.');});}
async function orderInvoice(id){const orders=await api('/api/orders'),o=orders.find(o=>o.id===Number(id));if(!o)return;const normalized=v=>String(v||'').replace(/\D/g,'').replace(/^01/,'8801');const matches=state.customers.filter(c=>normalized(c.phone)===normalized(o.phone));const c=matches.length===1?matches[0]:null;selectedOrder={...o,customer_id:c?.id||''};location.hash='billing';if(route==='billing')navigate();}
function orderQR(){modal('Your customer order link',`<div style="text-align:center"><img src="/qr/online_order.svg" alt="Customer order portal QR" width="220" height="220"><h2>${esc(state.settings.business_name||'DigitXBD')}</h2><p>Scan to upload documents and place a printing order.</p><input value="${esc(state.order_url)}" readonly id="order-url"><p class="muted">For customers on other devices, set a reachable Public URL in Settings and configure your server’s domain or LAN address.</p><div class="head-actions" style="justify-content:center">${btn('copy-order','Copy link','primary')}${btn('print','Print QR poster')}</div></div>`);}
function inventoryAdd(){modal('Add a material',`<form><div class="form-grid">${field('Material name','name','','text','required')}${field('Unit','unit','sheet','text','required')}${field('Reorder level','reorder','100','number','min="0" step="0.001"')}${field('Supplier','supplier')}</div><div class="modal-footer"><button class="primary" type="submit">Add material</button></div></form>`,async data=>{await api('/api/inventory','POST',data);closeModal();navigate();toast('Material added.');});}
function stockMove(id){modal('Record stock movement',`<form><div class="form-grid">${dateField()}<label>Movement type<select name="kind">${opt(state.role==='owner'?['Purchased','Opening','Used']:['Used'])}</select></label>${field('Quantity','quantity','','number','min="0.001" step="0.001" required')}${field('Purchase cost per unit (৳)','unit_cost','0','number','min="0" step="0.01"')}<label class="full">Notes<textarea name="notes"></textarea></label></div><label class="check"><input name="record_cash" type="checkbox" checked>Record purchase cash outflow as Stock Purchase (not operating expense).</label><div class="modal-footer"><button class="primary" type="submit">Save movement</button></div></form>`,async(data,form)=>{data.item_id=id;data.record_cash=$('[name=record_cash]',form).checked;await api('/api/inventory/movement','POST',data);closeModal();await reload();navigate();toast('Stock updated.');});}
function serviceAdd(){modal('Save a service price',`<form><div class="form-grid">${field('Service name','name','','text','required')}${field('Unit','unit','page')}${field('Selling price per unit (৳)','price','','number','min="0" step="0.01" required')}${field('Known production cost per unit (৳)','cost','','number','min="0" step="0.01" required')}</div><div class="modal-footer"><button class="primary" type="submit">Save service</button></div></form>`,async data=>{await api('/api/services','POST',data);closeModal();await reload();navigate();toast('Service saved.');});}
function userAdd(){modal('Add team member',`<form><div class="form-grid">${field('Username','username','','text','required minlength="3" maxlength="40"')}${field('Password (12+ characters)','password','','password','required minlength="12" autocomplete="new-password"')}<label>Role<select name="role">${opt(['staff','owner'])}</select></label></div><p class="muted">Staff can bill, receive payments, record expenses, manage orders, and record stock use. Owners also manage financial corrections, capital, settings, users, and backups.</p><div class="modal-footer"><button class="primary" type="submit">Create user</button></div></form>`,async data=>{await api('/api/users','POST',data);closeModal();navigate();toast('User created.');});}
function userEdit(id,active){modal('Manage team account',`<form><div class="form-grid">${field('New password (optional)','password','','password','minlength="12" autocomplete="new-password"')}<label>Status<select name="active"><option value="1" ${active==='1'?'selected':''}>Active</option><option value="0" ${active==='0'?'selected':''}>Disabled</option></select></label></div><div class="modal-footer"><button class="primary" type="submit">Save access</button></div></form>`,async data=>{data.active=data.active==='1';await api('/api/users/'+id,'PUT',data);closeModal();navigate();toast('Access updated.');});}
async function auditView(){const audit=await api('/api/audit');modal('Audit trail · Latest 500 actions',table(['Time (UTC)','User','Action','Detail'],audit.map(a=>`<tr><td>${esc(a.created)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td style="max-width:380px;word-break:break-word">${esc(a.detail)}</td></tr>`).join('')));}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;try{if(action==='close-modal')closeModal();else if(action==='refresh'){await reload();navigate();}else if(action==='customer-add')customerAdd();else if(action==='customer-edit')customerEdit(el.dataset.id);else if(action==='statement')await statement(el.dataset.id);else if(action==='payment')paymentModal(el.dataset.id||'',el.dataset.related||'');else if(action==='item-add'){$('#invoice-items').insertAdjacentHTML('beforeend',itemLine());calcBill();}else if(action==='item-remove'){if($$('.item-group').length>1)el.closest('.item-group').remove();calcBill();}else if(action==='billing-mode'){$$('.tab-strip button').forEach(b=>b.classList.toggle('active',b===el));if(el.dataset.mode==='ledger')await ledgerView();else{$('#content').innerHTML=billingView();bindView();}}else if(action==='ledger-search')searchLedger();else if(action==='ledger-page')await ledgerView(Number(el.dataset.page),el.dataset.q,el.dataset.kind);else if(action==='new-invoice'){closeModal();selectedOrder=null;invoiceKey=crypto.randomUUID();location.hash='billing';navigate();}else if(action==='reminder')await reminder(el.dataset.id);else if(action==='expense-add')expenseModal();else if(action==='order-edit')await orderEdit(el.dataset.id);else if(action==='order-invoice')await orderInvoice(el.dataset.id);else if(action==='order-qr')orderQR();else if(action==='copy-order'){try{await navigator.clipboard.writeText(state.order_url);toast('Order link copied.');}catch{$('#order-url').select();toast('Select and copy the link above.');}}else if(action==='print')window.print();else if(action==='inventory-add')inventoryAdd();else if(action==='stock-move')stockMove(el.dataset.id);else if(action==='service-add')serviceAdd();else if(action==='service-remove'){await api('/api/services/'+el.dataset.id,'DELETE');await reload();navigate();toast('Saved service removed.');}else if(action==='user-add')userAdd();else if(action==='user-edit')userEdit(el.dataset.id,el.dataset.active);else if(action==='audit')await auditView();else if(action==='adjustment')adjustmentModal();else if(action==='refund')adjustmentModal(true);else if(action==='cost-edit'){const id=el.dataset.id;modal('Record total production cost',`<form>${field('Total cost for this invoice (৳)','cost',el.dataset.cost,'number','min="0" step="0.01" required')}<p class="muted">This corrects job profit, leaves the bill and payments unchanged, and is saved in the audit trail.</p><div class="modal-footer"><button class="primary" type="submit">Save cost</button></div></form>`,async data=>{await api('/api/transactions/'+id+'/cost','PUT',data);closeModal();await reload();await ledgerView();toast('Production cost updated.');});}}catch(error){toast(error.message);}});
document.addEventListener('change',async event=>{if(event.target.id!=='merchant-qr-image')return;const file=event.target.files[0];if(!file)return;event.target.disabled=true;try{if(file.size>8*1024*1024)throw Error('Choose an image smaller than 8 MB.');const form=new FormData();form.append('image',file);const response=await fetch('/api/merchant-qr',{method:'POST',headers:{'X-CSRF-Token':csrf},body:form});const data=await response.json();if(!response.ok)throw Error(data.error||'Upload failed.');const settingsForm=$('#settings-form'),draft=Object.fromEntries(new FormData(settingsForm));await reload();await navigate();for(const [name,value]of Object.entries(draft)){const input=$('[name="'+name+'"]','#settings-form');if(input&&input.type!=='file')input.value=value;}toast('Original merchant image saved. Invoices use the exact uploaded image.');}catch(error){toast(error.message);}finally{event.target.disabled=false;}});
$('#quick-invoice').addEventListener('click',()=>{selectedOrder=null;invoiceKey=crypto.randomUUID();location.hash='billing';if(route==='billing')navigate();});$('#menu-toggle').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));window.addEventListener('hashchange',navigate);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'){e.preventDefault();$('#quick-invoice').click();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();($('#customer-search')||$('#transaction-search')||$('[name=customer_id]'))?.focus();}});
(async()=>{try{await import('/static/react/app.js');await reload();await navigate();}catch(error){$('#content').innerHTML=`<div class="notice danger">${esc(error.message)}</div>`;}})();
